"use client";

import React, { useState, useEffect } from 'react';
import { db } from "@/lib/db";
import { LineChart, CheckCircle, BrainCircuit, RefreshCw, Zap, TrendingUp, Users } from 'lucide-react';
import Link from 'next/link';

export default function AnalyticsDashboardPage({ params }: { params: { username: string } }) {
  const { username } = params;
  const [patterns, setPatterns] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRunning, setIsRunning] = useState(false);

  const fetchPatterns = () => {
    setIsLoading(true);
    fetch(`/api/workspace/${username}/analytics`)
      .then(r => r.json())
      .then(data => {
        if (data.patterns) setPatterns(data.patterns);
        setIsLoading(false);
      });
  };

  useEffect(() => {
    fetchPatterns();
  }, [username]);

  const handleRunAnalytics = async () => {
    setIsRunning(true);
    try {
      const res = await fetch(`/api/workspace/${username}/analytics`, { method: 'POST' });
      if (res.ok) {
        alert("Analytics cycle complete. Re-fetching learned patterns.");
        fetchPatterns();
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col overflow-hidden">
      {/* Top Navbar */}
      <header className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-slate-900/50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-amber-500/20 border border-amber-500/30 flex items-center justify-center">
            <LineChart className="w-4 h-4 text-amber-400" />
          </div>
          <span className="font-bold text-white tracking-wide">Performance Intelligence</span>
        </div>
        <div className="text-sm text-slate-400">
          Learning Engine for <span className="text-amber-300 font-medium">@{username}</span>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-8 max-w-7xl mx-auto w-full">
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2">Learned Patterns</h1>
            <p className="text-slate-400">Knowledge extracted from your published content's performance.</p>
          </div>
          <button 
            onClick={handleRunAnalytics}
            disabled={isRunning}
            className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-xl font-medium transition-colors border border-white/10 disabled:opacity-50"
          >
            <RefreshCw className={`w-4 h-4 ${isRunning ? 'animate-spin' : ''}`} /> Run Analytics Engine
          </button>
        </div>

        {/* Explainability Timeline */}
        <div className="bg-slate-900/50 border border-amber-500/20 rounded-2xl p-6 mb-8 flex items-center justify-between">
          <div className="flex-1 text-center">
            <div className="text-xs uppercase tracking-wider text-slate-500 font-semibold mb-2">1. Publish</div>
            <div className="w-10 h-10 mx-auto rounded-full bg-slate-800 flex items-center justify-center border border-white/5">
              <Zap className="w-5 h-5 text-indigo-400" />
            </div>
          </div>
          <div className="flex-1 h-px bg-gradient-to-r from-transparent via-amber-500/50 to-transparent"></div>
          <div className="flex-1 text-center">
            <div className="text-xs uppercase tracking-wider text-slate-500 font-semibold mb-2">2. Measure</div>
            <div className="w-10 h-10 mx-auto rounded-full bg-slate-800 flex items-center justify-center border border-white/5">
              <LineChart className="w-5 h-5 text-emerald-400" />
            </div>
          </div>
          <div className="flex-1 h-px bg-gradient-to-r from-transparent via-amber-500/50 to-transparent"></div>
          <div className="flex-1 text-center">
            <div className="text-xs uppercase tracking-wider text-slate-500 font-semibold mb-2">3. Learn</div>
            <div className="w-10 h-10 mx-auto rounded-full bg-slate-800 flex items-center justify-center border border-white/5">
              <BrainCircuit className="w-5 h-5 text-amber-400" />
            </div>
          </div>
        </div>

        {/* Patterns List */}
        {isLoading ? (
          <div className="text-center py-20 text-slate-500"><RefreshCw className="w-8 h-8 animate-spin mx-auto mb-4" /> Loading Intelligence...</div>
        ) : patterns.length === 0 ? (
          <div className="text-center py-20 bg-slate-900 border border-white/5 rounded-2xl">
            <BrainCircuit className="w-12 h-12 text-slate-700 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-white mb-2">No Patterns Learned Yet</h3>
            <p className="text-slate-400 max-w-md mx-auto mb-6">Publish more content and link it in the Workspace to start extracting patterns.</p>
            <Link href={`/workspace/${username}`} className="bg-amber-600/20 hover:bg-amber-600/30 text-amber-500 border border-amber-500/30 px-6 py-3 rounded-xl transition-colors font-medium">
              Go to Workspace
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {patterns.map(p => (
              <div key={p.id} className="bg-slate-900 border border-white/10 hover:border-amber-500/50 rounded-2xl p-6 transition-all group flex flex-col">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-2 text-amber-400 bg-amber-500/10 px-3 py-1 rounded-lg border border-amber-500/20 text-sm font-bold">
                    <TrendingUp className="w-4 h-4" /> {p.averageLift}x Lift
                  </div>
                  <div className={`text-xs font-bold px-2.5 py-1 rounded-md ${
                    p.status === 'Validated' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-slate-800 text-slate-300'
                  }`}>
                    {p.status}
                  </div>
                </div>

                <h3 className="text-lg font-medium text-white mb-2 group-hover:text-amber-300 transition-colors">
                  {p.pattern}
                </h3>

                <div className="mt-4 pt-4 border-t border-white/5 flex items-center justify-between text-sm">
                  <div className="flex flex-col">
                    <span className="text-slate-500 text-xs uppercase tracking-wider font-semibold">Confidence</span>
                    <span className="text-white font-bold">{p.confidenceScore}%</span>
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="text-slate-500 text-xs uppercase tracking-wider font-semibold">Sample Size</span>
                    <span className="text-slate-300">{p.sampleSize} Posts</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}
